H,W=11,24
matches=[]
for r in range(H-3):
 for c in range(W-3):
  if all(grid[r+dr][c+dc]==0 for dr,dc in shape): matches.append((r,c))
out=[row[:] for row in grid]
for r,c in matches:
 for dr,dc in shape: out[r+dr][c+dc]=1
print('matches',matches,'count',len(matches))
print('\n'.join(' '.join(map(str,row)) for row in out))
print('output dims',len(out),set(map(len,out)))

